        price += 10;
    } else if (gender === 'female') {
        price -= 5;
    }

    if (incomeBracket === 'middle class') {
        price += 20;
    } else if (incomeBracket === 'upper class') {
        price += 50;
    }

    if (ethnicity === 'white') {
        price += 10;
    } else if (ethnicity === 'black') {
        price -= 10;
    }

    return price;
}

function displayPrices(prices) {
    // Implement your price display logic here
    // This is just a placeholder
    console.log('Price: ' + prices);
}
